      wordpressCategoryAmbiguous: 'Trang WordPress có nhiều chuyên mục cùng tên “{name}”, nên chưa đăng gì. Hãy đổi tên một chuyên mục trong trang quản trị, rồi đăng lại.',
      wordpressTagNotAllowed: 'Tài khoản WordPress đã kết nối không được tạo thẻ mới “{name}”, nên chưa đăng gì. Hãy nhờ quản trị viên tạo thẻ đó hoặc bỏ thẻ khỏi bài, rồi đăng lại.',
      pinterestSectionNotFound: 'Bảng Pinterest không còn phần đã chọn, nên chưa ghim gì. Hãy chọn phần khác hoặc bỏ chọn, rồi đăng lại.',
      discordThreadNameRequired: 'Discord không nhận bài vì webhook này thuộc kênh diễn đàn, nên chưa đăng gì. Hãy sửa bài, bật “Đăng vào kênh diễn đàn” trong thiết lập Discord, rồi đăng lại.',
